import socket
import threading
import select
allsocks = []

def acc():
	sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
	sock.bind("", 2555)
	sock.listen(5)
	while 1:
		newsock, remote = sock.accept()
		allsocks.append(newsock)


newthread = threading.Thread(target = acc)
