参见：[[C++:友元]]

== const对象 ==

定义对象前面加const，表示对象不能改变
{{{#!cplusplus
class clock{
    int hour, minute, second;
public:
    clock(int h, int m, int s)
       : hour(h), minute(m), second(s)
    {
    }
    void set_time(int h, int m, int s) {
        hour = h;
        minute = m;
        second = s;
    }
    void show_time() {
        cout << hour << minute << second;
    }
};
int main() {
    const int i = 10;
    cout << i*10;               // ok
    i++;                        // error!
    const clock  t(10, 30, 20);
    cout << t.second;           // ok
    t.second = 10;              // error
    t.set_time(10, 20, 10);      // error!
    t.show_time();               // error!
}
}}}

const对象不能调用普通的成员函数，即使这个函数并不修改数据成员。对于不修改数据成员的成员函数，可以在声明后面加const，表示这个成员函数不修改数据成员，这样的函数可以被const对象调用。
{{{#!cplusplus
class clock{
    int hour, minute, second;
public:
    clock(int h, int m, int s)
       : hour(h), minute(m), second(s)
    {
    }
    void set_time(int h, int m, int s) {
        hour = h;
        minute = m;
        second = s;
    }
    void show_time() const {
        cout << hour << minute << second;
    }
};
int main() {
    const int i = 10;
    cout << i*10;               // ok
    i++;                        // error!
    const clock  t(10, 30, 20);
    cout << t.second;           // ok
    t.second = 10;              // error
    t.set_time(10, 20, 10);      // error!
    t.show_time();               // ok
}
}}}

const成员函数可以被const对象调用，也可以被普通对象调用。
{{{#!cplusplus
int main() {
   const  clock  time(10, 20, 30);
   time.show_time();
   clock now(10, 10, 10);
   time.show_time();
}
}}}

常成员函数与非常成员函数可以重载
{{{#!cplusplus
class array {
private:
    int *p, size;
public:
    array(int s) {
        size = s;
        p = new int [ size ];
    }
    ~array() { delete[ ] p; }
    int & at( int i) {
         if( i < size) return p[i]; else throw out_of_range(); 
    }
    int at( int i) const  {
         if( i < size) return p[i]; else throw out_of_range(); 
    }
};
int main() {
    array a(10);
    a.at(5) = 5;
    const array b(5);
    b.at(5) = 5;      // error
}

}}}

