=== vector的实现 ===
vector的实现类似于数据结构中的顺序表

{{attachment:vector.jpg}}

{{{#!cplusplus
template<class T, class Alloc=alloc>
class vector {
public:
    typedef T value_type;
    typedef value_type* iterator;
    typedef value_type& reference;
    typedef size_t size_type;
protected:
    iterator start;
    iterator finish;
    iterator end_of_storage;


public:
    iterator begin() { return start; }
    iterator end() { return finish; }
    size_type size() const { //返回当前元素个数
        return size_type(end() - begin());
    }
    bool empty() const {
        return begin() == end();
    }
    reference operator[](size_type n) {
        return *(begin() + n);
    }
    reference front() {
        return *begin();
    }
    reference back() {
        return *(end() - 1);
    }
    size_type capacity() const {  //返回当前容量的大小
        return size_type(end_of_storage - begin()); 
    } 
    size_type reserve(size_type n); //改变容量的大小
    void push_back(const T& x) {
        if(finish != end_of_storage) {
            construct(finish, x);
            ++finish;
        } else {
            insert_aux(end(), x);
        }
    }
protected:
    typedef simple_alloc<value_type, Alloc> data_allocator;
    void deallocate() {
        if(start) data_allocator::deallocate(start, end_of_storage - start);
    }
    
    void insert_aux(iterator position, const T& x) {
        if(finish != end_of_storage) {
            construct(finish, *(finish-1));
            ++finish;
            T x_copy = x;
            copy_backward(position, finish-2, finish-1);
            *position = x_copy;
        } else {
            const size_type old_size = size();
            const size_type len = old_size != 0 ? 2 * old_size : 1;
            iterator new_start = data_allocator::alloate(len);
            iterator new_finish = new_start;
            try {
                new_finish = uninitialized_copy(start, position, new_start);
                construct(new_finish, x);
                ++ new_finish;
                new_finish = uninitialized_copy(position, finish, new_finish);
            } catch(...) {
                destroy(new_start, new_finish);
                data_allocator::deallocate(new_start, len);
                throw;
            }
            destroy(begin(), end());
            deallocate();
            start = new_start;
            finish = new_finish;
            end_of_storage = new_start + len;
        }
    }
};
}}}

== deque双端队列 ==
deque与vector相似，区别是deque两端都是开放的，两端插入删除都很快。在头文件<deque>中定义。
{{attachment:deque.jpg}}

实现：
{{attachment:deque_imp.jpg}}

可以随机访问，但速度比vector稍慢

迭代子是随机跌代子，是一种class而不是原始指针

操作非常相似，增加操作：push_front, pop_front，减少操作：reserve,capacity

任何插入和删除操作都可能使跌代子失效

例子：

例子：
{{{#!cplusplus
int main() {
    deque<string> coll;
    coll.assign (3, string("string"));
    coll.push_back ("last string");
    coll.push_front ("first string");
    copy (coll.begin(), coll.end(), ostream_iterator<string>(cout,"\n"));
    coll.pop_front();
    coll.pop_back();
    for (int i=1; i<coll.size(); ++i) {
        coll[i] = "another " + coll [i];
    }
    coll.resize (4, "resized string");
    copy (coll.begin(), coll.end(), ostream_iterator<string>(cout,"\n"));
}
}}}

== list链表 ==
一般为双链表实现

#include <list>
提供双向跌代子，不能随机访问
插入删除操作非常快速
插入删除操作不会使跌代子失效
提供了一些移动元素的算法，比通用算法更快
{{{#!cplusplus
c1.swap(c2)：交换两个链表的内容
c.remove(val)
c.remove_if(predictor)
