square = lambda y: y*y
}}}
 1. {{{
(define (sqrt x)
  (define (good-enough? guess x)
    (< (abs (- (square guess) x)) 0.001))
  (define (improve guess x)
    (average guess (/ x guess)))
  (define (sqrt-iter guess x)
    (if (good-enough? guess x)
        guess
        (sqrt-iter (improve guess x) x)))
  (sqrt-iter 1.0 x))
}}}{{{#!python
def sqrt(x):
    good_enough = lambda guess, x: abs(square(guess)-x)< 0.001
    improve = lambda guess, x: average(guess, x/guess)
    sqrt_iter = lambda guess, x: guess if good_enough(guess, x) else sqrt_iter(improve(guess, x), x)
    return sqrt_iter(1.0, x)
}}}
 1. {{{
(define (sqrt x)
  (define (good-enough? guess)
    (< (abs (- (square guess) x)) 0.001))
  (define (improve guess)
    (average guess (/ x guess)))
  (define (sqrt-iter guess)
    (if (good-enough? guess)
        guess
        (sqrt-iter (improve guess))))
  (sqrt-iter 1.0))
}}}{{{#!python
def sqrt(x):
    good_enough = lambda guess: abs(square(guess)-x)< 0.001
    improve = lambda guess: average(guess, x/guess)
    sqrt_iter = lambda guess: guess if good_enough(guess) else sqrt_iter(improve(guess))
    return sqrt_iter(1.0)
}}}
